T.en['op02.quiz'] = [
  {q:'You need to open your workstation on Filling, Line 1. You are at the Cockpit main view. What is the correct sequence?',opts:['Click Station View on the Line 1 card directly. It is faster.','Click Drill-down on Line 1 → find Filling segment → click Station View on Filling','Click the Line 1 card title → select Filling from a dropdown'],correct:1,exp:'Correct: Cockpit → Drill-down on Line card → Segment level → Station View on Segment card. Station View at Line level shows limited data because orders are managed at Segment level.',vis:'In TilliT: → Drill-down button on Line card → Level 2 appears → Station View button on the Filling card.'},
  {q:'The plant has many lines running and the Cockpit feels cluttered. What do you use to see only your own line?',opts:['The + Filter button in the Cockpit toolbar','Switch the card view to Compact','Ask a Superuser to hide the other lines'],correct:0,exp:'The + Filter button narrows the Cockpit to your area: pick a specific Asset (one line or segment) or an Asset Class (every segment of a type across all lines). It only changes what you see, never the lines themselves.',vis:'Cockpit toolbar → + Filter → choose Asset or Asset Class → Cockpit shows only your selection.'},
  {q:'You want one-click access to your segment\'s Station View from next shift on, without going through the Cockpit again. What do you do?',opts:['Click the pin icon in the Station View top bar','Bookmark the page in your browser','Ask IT to set it as your homepage'],correct:0,exp:'The Pin button, in the top bar of any Station View, adds a permanent shortcut to the TilliT left menu. Next shift: one click from the menu, no need to Drill-down through the Cockpit again.',vis:'Station View top bar → pin icon → shortcut added to left menu → one click next time.'}
];

T.it['op02.quiz'] = [
  {q:'Devi aprire la tua postazione di lavoro su Riempimento, Linea 1. Sei nella vista principale del Cockpit. Qual è la sequenza corretta?',opts:['Clicca Station View sulla scheda Linea 1 direttamente. È più veloce.','Clicca Drill-down sulla Linea 1 → trova il segmento Riempimento → clicca Station View su Riempimento','Clicca il titolo della scheda Linea 1 → seleziona Riempimento da un menu a tendina'],correct:1,exp:'Corretto: Cockpit → Drill-down sulla scheda Linea → livello Segmento → Station View sulla scheda Segmento. Station View a livello Linea mostra dati limitati perché gli ordini sono gestiti a livello Segmento.',vis:'In TilliT: → pulsante Drill-down sulla scheda Linea → appare il Livello 2 → pulsante Station View sulla scheda Riempimento.'},
  {q:'L\'impianto ha molte linee attive e il Cockpit sembra affollato. Cosa usi per vedere solo la tua linea?',opts:['Il pulsante + Filter nella toolbar del Cockpit','Passare la vista scheda a Compact','Chiedere a un Superuser di nascondere le altre linee'],correct:0,exp:'Il pulsante + Filter riduce il Cockpit alla tua area: scegli un Asset specifico (una linea o un segmento) o una Asset Class (ogni segmento di un tipo su tutte le linee). Cambia solo cosa vedi, mai le linee stesse.',vis:'Toolbar del Cockpit → + Filter → scegli Asset o Asset Class → il Cockpit mostra solo la tua selezione.'},
  {q:'Vuoi un accesso a un clic alla Station View del tuo segmento dal prossimo turno, senza rifare il Cockpit ogni volta. Cosa fai?',opts:['Clicchi l\'icona pin nella barra superiore della Station View','Metti un segnalibro nel browser','Chiedi all\'IT di impostarla come pagina iniziale'],correct:0,exp:'Il pulsante Pin, nella barra superiore di qualsiasi Station View, aggiunge un collegamento permanente al menu sinistro di TilliT. Al prossimo turno: un clic dal menu, senza rifare il Drill-down dal Cockpit.',vis:'Barra superiore della Station View → icona pin → collegamento aggiunto al menu sinistro → un clic la prossima volta.'}
];

T.en['op02.cf'] = [
  {k:'line level',r:'Station View at Line level shows very limited data because orders are managed at Segment level. Each segment runs its own independent operation. You need to Drill-down to Segment level first, then use Station View from there.'},
  {k:'yellow',r:'Yellow means Starved: the machine is running but there is no product arriving from the upstream segment. Orange is the opposite: the machine is fine but the downstream buffer is full and product cannot move forward.'},
  {k:'orange',r:'Orange means Blocked: the downstream buffer is full and the segment cannot discharge product forward. The machine itself is running normally. Compare to Red (machine fault) and Yellow (no incoming product from upstream).'},
  {k:'expand',r:'Use Expanded view at the start of your shift. It adds an Activities Open counter directly on each card. You can spot which segments have outstanding tasks without opening each Station View individually.'},
  {k:'filter',r:'The Filter button is at the top of the Cockpit. It lets you show only your line, reducing visual noise when the plant has many lines active.'},
  {k:'pin',r:'The Pin button is in the top bar of any Station View. Click it once to add a permanent shortcut to the TilliT left menu. Next shift: one click from the menu, no Cockpit needed.'},
  {k:'drill',r:'Drill-down opens Level 2: the Segment Overview for that line. You see all segments: Depalletizing, Filling, Labeling, Packing, Palletizing. Each has its own status colour and data.'},
  {k:'red',r:'Red means Stopped: a machine fault or a manual stop. It needs your attention first: open Station View and check the Downtime Events panel for the reason.'},
  {k:'green',r:'Green means Running: the segment is producing normally. Nothing to fix, just keep an eye on OEE and run rate.'},
  {k:'idle',r:'Grey or dark means Idle: no active order, or no signal at all from the machine. Check whether an order should be running on that segment.'},
];
T.en['op02.cf.default'] = 'Here\'s the idea. In TilliT the Cockpit two-level structure gives you a plant overview at Level 1 before drilling into your specific segment at Level 2. The status colours come directly from PLC sensors in real time. Is there a specific aspect of this module you would like me to clarify?';

T.it['op02.cf'] = [
  {k:'livello linea',r:'Station View a livello Linea mostra dati molto limitati perché gli ordini sono gestiti a livello Segmento. Ogni segmento gestisce la propria operazione indipendente. Devi prima eseguire il Drill-down al livello Segmento, poi usare Station View da lì.'},
  {k:'giallo',r:'Giallo significa In carenza: la macchina è in funzione ma non arriva prodotto dal segmento a monte. Arancione è il contrario: la macchina funziona bene ma il buffer a valle è pieno e il prodotto non può avanzare.'},
  {k:'arancione',r:'Arancione significa Bloccato: il buffer a valle è pieno e il segmento non può scaricare il prodotto in avanti. La macchina stessa funziona normalmente. Confronta con Rosso (guasto macchina) e Giallo (nessun prodotto in arrivo da monte).'},
  {k:'espansa',r:'Usa la vista Espansa all\'inizio del tuo turno. Aggiunge un contatore Attività aperte direttamente su ogni scheda. Puoi individuare quali segmenti hanno attività in sospeso senza aprire ogni Station View singolarmente.'},
  {k:'filtro',r:'Il pulsante Filtro si trova in cima al Cockpit. Permette di mostrare solo la tua linea, riducendo il rumore visivo quando l\'impianto ha molte linee attive.'},
  {k:'pin',r:'Il pulsante Pin si trova nella barra superiore di qualsiasi Station View. Cliccalo una volta per aggiungere un collegamento permanente al menu sinistro di TilliT. Al prossimo turno: un clic dal menu, senza bisogno del Cockpit.'},
  {k:'drill',r:'Il Drill-down apre il Livello 2: la Panoramica Segmenti per quella linea. Vedi tutti i segmenti: Depalletizzazione, Riempimento, Etichettatura, Confezionamento, Palletizzazione. Ognuno ha il proprio colore di stato e i propri dati.'},
  {k:'rosso',r:'Rosso significa Fermo: un guasto macchina o uno stop manuale. Richiede attenzione: apri la Station View e controlla il pannello Eventi di Fermo per il motivo.'},
  {k:'verde',r:'Verde significa In funzione: il segmento sta producendo normalmente. Niente da correggere, tieni d\'occhio OEE e velocità di produzione.'},
  {k:'inattivo',r:'Grigio o scuro significa Inattivo: nessun ordine attivo, o nessun segnale dalla macchina. Controlla se su quel segmento dovrebbe essere in corso un ordine.'},
];
T.it['op02.cf.default'] = 'Ecco l\'idea. In TilliT la struttura a due livelli del Cockpit offre una panoramica dell\'impianto al Livello 1 prima di approfondire il tuo segmento specifico al Livello 2. I colori di stato provengono direttamente dai sensori PLC in tempo reale. C\'è un aspetto specifico di questo modulo che vorresti che chiarissi?';

T.en['op02.pr'] = [
  'Good. Orange = Blocked (downstream buffer full) and Red = Stopped (machine fault). Now: which one demands immediate action from you as an operator, and why?',
  'Think about this: a Blocked segment may resolve on its own once the downstream catches up. A Stopped segment means something broke or was manually halted. It needs action. Which is more urgent?',
  'Exactly. Red (Stopped) is the priority because it will not resolve itself. Your first step in TilliT: open Station View for Line 2 and check the Downtime Events panel for unassigned stops. Then monitor Line 1 (Orange); it may clear automatically.',
  'Well done. You identified both colours correctly and know where to act in TilliT. Red first, then Orange. That is exactly the right shift-start approach.'
];

T.it['op02.pr'] = [
  'Bene. Arancione = Bloccato (buffer a valle pieno) e Rosso = Fermo (guasto macchina). Ora: quale dei due richiede un\'azione immediata da parte tua come operatore, e perché?',
  'Ragionaci: un segmento Bloccato può risolversi da solo una volta che il downstream recupera. Un segmento Fermo significa che qualcosa si è rotto o è stato fermato manualmente. Richiede un intervento. Quale è più urgente?',
  'Esatto. Rosso (Fermo) è la priorità perché non si risolve da solo. Il tuo primo passo in TilliT: apri Station View per la Linea 2 e controlla il pannello Eventi di Fermo per le fermate non assegnate. Poi monitora la Linea 1 (Arancione); potrebbe risolversi automaticamente.',
  'Ottimo lavoro. Hai identificato correttamente entrambi i colori e sai dove agire in TilliT. Prima Rosso, poi Arancione. È esattamente il giusto approccio a inizio turno.'
];

// ── DANSK dynamic content ──────────────────────────────────────────

T.da['op01.quiz'] = [
  {q:'Du åbner TilliT-loginsiden for første gang. Der er Username- og Password-felter og en blå "Corporate Login"-knap. Hvad gør du?',
   opts:['Udfyld Username og Password, og klik så Login','Klik på Corporate Login-knappen. Ignorér Username- og Password-felterne.','Klik "Forgot your password?" for at oprette en ny TilliT-adgangskode'],
   correct:1,
   exp:'TilliT bruger Single Sign-On (SSO) via Microsoft. Corporate Login er altid det rigtige valg: det omdirigerer til din virksomheds Microsoft-loginside. Username/Password-felterne bruges ikke af operatører.',
   vis:'På TilliT-loginsiden: ignorér Username/Password-felterne → klik på den blå <strong>Corporate Login</strong>-knap nederst.'},
  {q:'To kolleger åbner den samme TilliT og ser forskellige venstremenuer. Hvad afgør, hvad hver af dem ser?',
   opts:['Deres rolle: Operator eller Superuser','Hvilket sprog de har valgt','Hvilken browser de bruger'],
   correct:0,
   exp:'Venstremenuen afhænger af din rolle. Operators ser Assets, Cockpit og Insights. Superusers ser også Activities, Users, Settings og History, vist under en skillelinje i samme menu.',
   vis:'Venstremenu: Operator = Assets/Cockpit/Insights. Superuser = det samme + Activities/Users/Settings/History (fremhævet, under skillelinjen).'},
  {q:'Du vil skifte TilliT-interfacesproget til italiensk. Hvor klikker du?',
   opts:['Indstillinger → Sprog i venstremenuen','Globusikonet i øverste højre bjælke','Din initial-cirkel øverst til højre, derefter Profil → Sprog'],
   correct:1,
   exp:'Globusikonet er i øverste højre bjælke, mellem klokken og hjælpeikonet. Klik på det, og en sprogmenu vises. Vælg Italiano, og siden opdateres med alle Systemetiketter opdateret.',
   vis:'Topbjælke øverst til højre → globusikon → sprogmenu → vælg Italiano → siden opdateres.'}
];

T.da['op02.quiz'] = [
  {q:'Du skal åbne din arbejdsstation på Filling, Line 1. Du er i Cockpit-hovedvisningen. Hvad er den korrekte rækkefølge?',opts:['Klik Station View på Line 1-kortet direkte. Det er hurtigere.','Klik Drill-down på Line 1 → find Filling-segmentet → klik Station View på Filling','Klik Line 1-korttitlen → vælg Filling fra en dropdown'],correct:1,exp:'Korrekt: Cockpit → Drill-down på Linje-kort → Segment-niveau → Station View på Segment-kort. Station View på Linje-niveau viser begrænsede data, fordi ordrer håndteres på Segment-niveau.',vis:'I TilliT: → Drill-down-knap på Linje-kort → Niveau 2 vises → Station View-knap på Filling-kortet.'},
  {q:'Anlægget har mange linjer i gang, og Cockpittet føles rodet. Hvad bruger du til kun at se din egen linje?',opts:['+ Filter-knappen i Cockpit-værktøjslinjen','Skift kortvisningen til Kompakt','Bed en Superuser om at skjule de andre linjer'],correct:0,exp:'+ Filter-knappen indsnævrer Cockpittet til dit område: vælg et specifikt Asset (én linje eller ét segment) eller en Asset Class (alle segmenter af en type på tværs af linjer). Den ændrer kun, hvad du ser, aldrig selve linjerne.',vis:'Cockpit-værktøjslinje → + Filter → vælg Asset eller Asset Class → Cockpit viser kun dit valg.'},
  {q:'Du vil have adgang med ét klik til dit segments Station View fra næste vagt, uden at skulle gennem Cockpittet igen. Hvad gør du?',opts:['Klik på pin-ikonet i Station Views topbjælke','Sæt et bogmærke i din browser','Bed IT om at sætte den som din startside'],correct:0,exp:'Pin-knappen, i topbjælken på enhver Station View, tilføjer en permanent genvej til TilliT-venstremenuen. Næste vagt: ét klik fra menuen, ingen grund til at lave Drill-down via Cockpittet igen.',vis:'Station View topbjælke → pin-ikon → genvej tilføjet til venstremenu → ét klik næste gang.'}
];

T.da['op02.cf'] = [
  {k:'linje niveau',r:'Station View på Linje-niveau viser meget begrænsede data, fordi ordrer håndteres på Segment-niveau. Hvert segment kører sin egen uafhængige operation. Du skal først Drill-down til Segment-niveau og derefter bruge Station View derfra.'},
  {k:'gul',r:'Gul betyder Udsultet: maskinen kører, men der kommer intet produkt fra upstream-segmentet. Orange er det modsatte: maskinen er fin, men downstream-bufferen er fuld, og produktet kan ikke bevæge sig fremad.'},
  {k:'orange',r:'Orange betyder Blokeret: downstream-bufferen er fuld, og segmentet kan ikke afsætte produkt fremad. Selve maskinen kører normalt. Sammenlign med Rød (maskinfejl) og Gul (intet indkommende produkt fra upstream).'},
  {k:'udvid',r:'Brug Udvidet visning ved starten af dit skift. Den tilføjer en Activities Open-tæller direkte på hvert kort. Du kan se, hvilke segmenter der har udestående opgaver, uden at åbne hver Station View enkeltvis.'},
  {k:'filter',r:'Filter-knappen er øverst i Cockpit. Den lader dig kun vise din linje, så det visuelle støj reduceres, når anlægget har mange aktive linjer.'},
  {k:'pin',r:'Pin-knappen er i topbjælken på enhver Station View. Klik på den én gang for at tilføje en permanent genvej til TilliT-venstremenuen. Næste skift: ét klik fra menuen, ingen Cockpit nødvendig.'},
  {k:'drill',r:'Drill-down åbner Niveau 2: Segmentoversigten for den linje. Du ser alle segmenter: Depalletizing, Filling, Labeling, Packing, Palletizing. Hvert har sin egen statusfarve og data.'},
  {k:'rød',r:'Rød betyder Stoppet: en maskinfejl eller et manuelt stop. Det kræver din opmærksomhed først: åbn Station View og tjek Downtime Events-panelet for årsagen.'},
  {k:'grøn',r:'Grøn betyder I gang: segmentet producerer normalt. Intet at rette, hold blot øje med OEE og produktionshastighed.'},
  {k:'inaktiv',r:'Grå eller mørk betyder Inaktiv: ingen aktiv ordre, eller intet signal overhovedet fra maskinen. Tjek om en ordre burde køre på det segment.'},
];
T.da['op02.cf.default'] = 'Sådan hænger det sammen. I TilliT giver Cockpittets struktur i to niveauer dig et anlægsoverblik på Niveau 1, før du driller ned i dit specifikke segment på Niveau 2. Statusfarverne kommer direkte fra PLC-sensorer i realtid. Er der et specifikt aspekt af dette modul, du gerne vil have mig til at afklare?';

T.da['op02.pr'] = [
  'Godt. Orange = Blokeret (downstream-buffer fuld) og Rød = Stoppet (maskinfejl). Nu: hvilken af dem kræver øjeblikkelig handling fra dig som operatør, og hvorfor?',
  'Tænk over dette: et Blokeret segment kan løse sig selv, når downstream indhenter. Et Stoppet segment betyder, at noget gik i stykker eller blev standset manuelt. Det kræver handling. Hvilket er mest presserende?',
  'Præcis. Rød (Stoppet) er prioriteten, fordi det ikke løser sig selv. Dit første skridt i TilliT: åbn Station View for Line 2 og tjek Downtime Events-panelet for ikke-tildelte stop. Overvåg derefter Line 1 (Orange); det rydder måske automatisk.',
  'Godt klaret. Du identificerede begge farver korrekt og ved, hvor du skal handle i TilliT. Rød først, så Orange. Det er præcis den rigtige tilgang ved skiftstart.'
];

