T.zh['op01.quiz'] = [
  {q:'你第一次打开 TilliT 登录页。页面上有 Username 和 Password 字段以及一个蓝色的 "Corporate Login" 按钮。你会怎么做？',
   opts:['填写 Username 和 Password，然后点击 Login','点击 Corporate Login 按钮，忽略 Username 和 Password 字段。','点击 "Forgot your password?" 来创建新的 TilliT 密码'],
   correct:1,
   exp:'TilliT 通过 Microsoft 使用单点登录 (SSO)。Corporate Login 始终是正确选择：它会重定向到你公司的 Microsoft 登录页。Username/Password 字段不被操作员使用。',
   vis:'在 TilliT 登录页：忽略 Username/Password 字段 → 点击底部蓝色的 <strong>Corporate Login</strong> 按钮。'},
  {q:'两位同事打开同一个 TilliT，看到的左侧菜单却不同。是什么决定了各自看到的内容？',
   opts:['他们的角色：Operator 还是 Superuser','他们选择的语言','他们使用的浏览器'],
   correct:0,
   exp:'左侧菜单取决于你的角色。Operator 会看到 Assets、Cockpit 和 Insights。Superuser 还会看到 Activities、Users、Settings 和 History，显示在同一菜单的分隔线下方。',
   vis:'左侧菜单：Operator = Assets/Cockpit/Insights。Superuser = 相同内容 + Activities/Users/Settings/History（突出显示，在分隔线下方）。'},
  {q:'你想把 TilliT 界面语言切换为意大利语。你点击哪里？',
   opts:['左侧菜单中的 设置 → 语言','右上角栏中的地球图标','右上角的姓名缩写圆圈，然后 个人资料 → 语言'],
   correct:1,
   exp:'地球图标在右上角栏，位于铃铛和帮助图标之间。点击它会出现语言下拉菜单。选择 Italiano，页面将刷新并更新所有系统标签。',
   vis:'右上角栏 → 地球图标 → 语言菜单 → 选择 Italiano → 页面刷新。'}
];

T.zh['op02.quiz'] = [
  {q:'你需要打开 Filling, Line 1 上的工作站。你在 Cockpit 主视图。正确的顺序是什么？',opts:['直接在 Line 1 卡片上点击 Station View，更快。','在 Line 1 上点击 Drill-down → 找到 Filling 段 → 在 Filling 上点击 Station View','点击 Line 1 卡片标题 → 从下拉菜单中选择 Filling'],correct:1,exp:'正确：Cockpit → 在生产线卡片上 Drill-down → 段级别 → 在段卡片上 Station View。生产线级别的 Station View 显示数据有限，因为订单在段级别管理。',vis:'在 TilliT 中：→ 生产线卡片上的 Drill-down 按钮 → 出现第 2 级 → Filling 卡片上的 Station View 按钮。'},
  {q:'工厂有很多产线在运行，Cockpit 看起来很杂乱。你用什么只查看自己的产线？',opts:['Cockpit 工具栏中的 + Filter 按钮','把卡片视图切换为 Compact','让 Superuser 把其他产线隐藏'],correct:0,exp:'+ Filter 按钮把 Cockpit 缩小到你的区域：选择一个具体的 Asset（一条产线或一个段），或一个 Asset Class（所有产线上同类型的段）。它只改变你看到的内容，不会改变产线本身。',vis:'Cockpit 工具栏 → + Filter → 选择 Asset 或 Asset Class → Cockpit 只显示你的选择。'},
  {q:'你希望从下个班次开始一键进入你所在段的 Station View，而不用每次都经过 Cockpit。你会怎么做？',opts:['点击 Station View 顶部栏中的 pin 图标','在浏览器中添加书签','让 IT 把它设为你的主页'],correct:0,exp:'Pin 按钮位于任意 Station View 的顶部栏，会在 TilliT 左侧菜单中添加一个永久快捷方式。下个班次：从菜单一键直达，无需再通过 Cockpit 进行 Drill-down。',vis:'Station View 顶部栏 → pin 图标 → 快捷方式已添加到左侧菜单 → 下次一键直达。'}
];

T.zh['op02.cf'] = [
  {k:'生产线级别',r:'生产线级别的 Station View 显示的数据非常有限，因为订单在段级别管理。每个段运行自己独立的操作。你需要先 Drill-down 到段级别，然后从那里使用 Station View。'},
  {k:'黄色',r:'黄色表示缺料：机器在运行，但没有来自上游段的产品到达。橙色相反：机器正常，但下游缓冲区已满，产品无法向前移动。'},
  {k:'橙色',r:'橙色表示阻塞：下游缓冲区已满，段无法将产品向前排出。机器本身正常运行。与红色（机器故障）和黄色（无上游来料）相比较。'},
  {k:'展开',r:'在班次开始时使用展开视图。它直接在每张卡片上增加 Activities Open 计数。你可以发现哪些段有未完成的任务，而无需逐个打开 Station View。'},
  {k:'筛选',r:'Filter 按钮在 Cockpit 顶部。它让你只显示你的生产线，在工厂有许多生产线活动时减少视觉干扰。'},
  {k:'pin',r:'Pin 按钮在任何 Station View 的顶部栏。点击一次即可向 TilliT 左侧菜单添加永久快捷方式。下个班次：从菜单一键直达，无需 Cockpit。'},
  {k:'drill',r:'Drill-down 打开第 2 级：该生产线的段概览。你会看到所有段：Depalletizing、Filling、Labeling、Packing、Palletizing。每个都有自己的状态颜色和数据。'},
  {k:'红色',r:'红色表示 Stopped：机器故障或手动停止。需要你优先处理：打开 Station View 并检查 Downtime Events 面板了解原因。'},
  {k:'绿色',r:'绿色表示 Running：该段正在正常生产。无需处理，只需留意 OEE 和生产速度。'},
  {k:'空闲',r:'灰色或暗色表示 Idle：没有活动订单，或机器完全没有信号。请检查该段是否应该有订单在运行。'},
];
T.zh['op02.cf.default'] = '是这样的。在 TilliT 中，Cockpit 的两级结构在第 1 级为你提供工厂概览，然后在第 2 级深入到你的具体段。状态颜色直接来自 PLC 传感器，实时更新。关于本模块，有什么具体方面需要我说明吗？';

T.zh['op02.pr'] = [
  '很好。橙色 = 阻塞（下游缓冲区已满），红色 = 停止（机器故障）。那么：作为操作员，哪一个需要你立即采取行动，为什么？',
  '想一想：阻塞的段在下游赶上后可能自行解决。停止的段意味着有东西损坏或被手动停止。它需要采取行动。哪个更紧急？',
  '正是如此。红色（停止）是优先级，因为它不会自行解决。你在 TilliT 中的第一步：打开 Line 2 的 Station View，检查 Downtime Events 面板中未分配的停机。然后监控 Line 1（橙色）；它可能会自动恢复。',
  '做得好。你正确识别了两种颜色，并知道在 TilliT 中何处采取行动。先红色，后橙色。这正是班次开始时的正确做法。'
];

