/* ══════════════════════════════════════════════════════════════════
   OP-03 · Station View — i18n (appended; T.<lang> objects already exist)
   EN + IT authoritative. DA/ZH/NL appended separately (native review pending).
   ══════════════════════════════════════════════════════════════════ */

/* ---------- ENGLISH ---------- */
Object.assign(T.en, {











  'quiz.lbl.op03':"Question {n} of 3 · OP-03",


});
T.en['op03.quiz']=[
  {q:"In Station View, what is the main purpose of the panel that slides in from the right?",opts:["It shows the Cockpit overview of every line","It is where the Activity you select in the work list opens, so you can Claim and Submit it","It lists the site's raw materials"],correct:1,exp:"The execution panel slides in from the right: the activity you pick in the work list opens there to be claimed and submitted.",vis:"Right: click an activity → the panel slides over → Claim → fill the form → Submit."},
  {q:"You open the Activities list in the right column and it looks short. Which filter is applied by default?",opts:["No filter — it always shows every activity","The 'Active' filter — only active activities, newest first","A filter by operator name"],correct:1,exp:"The Activities tab defaults to the Active filter, so only tasks still to do are shown. Remove the chip to see completed ones too.",vis:"Activities tab → chip 'Active ×' → only active activities for the selected order."},
  {q:"Where in Station View do you read the running order — SKU, actual vs target quantity, OEE and order status?",opts:["In the right column, Orders tab","In the left column, the PO Area","In the right-hand action panel"],correct:1,exp:"The left column (PO Area) shows the running order: number, SKU, quantities, speed, OEE and status.",vis:"Left column = PO Area: order #, SKU, produced/target, OEE, status."}
];
T.en['op03.cf']=[
  {k:'column',r:"Station View has two columns and an action panel: left = the PO Area (your order), right = the work list (Activities, Orders, Events). A panel slides in from the right when you claim and submit a task."},
  {k:'claim',r:"Claiming assigns the activity to you. Until claimed it is unassigned. Once claimed the form becomes editable; some activities are auto-claimed and skip this step."},
  {k:'run rate',r:"Run Rate opens a speed chart: live speed (blue) vs the order target (green) and the machine nominal (yellow), plus the hourly average. If blue sits below green you are under target."},
  {k:'activities',r:"The Activities tab in the right column is your task list, filtered to Active by default. The blue counter on the left shows how many are still open."},
  {k:'suspend',r:"Suspend Order pauses production and preserves counters; Resume continues from where it stopped. Complete Order closes it permanently. Use Suspend for a temporary interruption."},
  {k:'segment',r:"The coloured segment button in the top bar shows the machine state (same Cockpit colours). Clicking it opens the Downtime Events panel to assign a stop reason — covered in OP-06."},
  {k:'oee',r:"OEE = Availability × Performance × Quality. The three shift percentages are in the top bar. A low figure points to stops, speed loss or rejects."}
];

/* ---------- ITALIANO ---------- */
Object.assign(T.it, {











  'quiz.lbl.op03':"Domanda {n} di 3 · OP-03",


});
T.it['op03.quiz']=[
  {q:"Nella Station View, qual è lo scopo principale del pannello che scorre da destra?",opts:["Mostra la panoramica Cockpit di ogni linea","È dove si apre l'Activity che selezioni nella lista di lavoro, così puoi fare Claim e Submit","Elenca le materie prime del sito"],correct:1,exp:"Il pannello di esecuzione scorre da destra: l'attività che scegli nella lista di lavoro si apre lì per essere presa in carico e inviata.",vis:"Destra: clicca un'attività → il pannello scorre sopra → Claim → compila il modulo → Submit."},
  {q:"Apri la lista Activities nella colonna destra e sembra corta. Quale filtro è applicato di default?",opts:["Nessun filtro — mostra sempre ogni attività","Il filtro 'Active' — solo le attività attive, dalle più recenti","Un filtro per nome operatore"],correct:1,exp:"La scheda Activities usa di default il filtro Active, quindi mostra solo le attività da fare. Rimuovi il chip per vedere anche quelle completate.",vis:"Scheda Activities → chip 'Active ×' → solo le attività attive dell'ordine selezionato."},
  {q:"Dove nella Station View leggi l'ordine in corso — SKU, quantità reale rispetto al target, OEE e stato dell'ordine?",opts:["Nella colonna destra, scheda Orders","Nella colonna sinistra, la PO Area","Nel pannello di azione a destra"],correct:1,exp:"La colonna sinistra (PO Area) mostra l'ordine in corso: numero, SKU, quantità, velocità, OEE e stato.",vis:"Colonna sinistra = PO Area: n° ordine, SKU, prodotto/target, OEE, stato."}
];
T.it['op03.cf']=[
  {k:'colonn',r:"La Station View ha due colonne e un pannello di azione: sinistra = la PO Area (il tuo ordine), destra = la lista di lavoro (Activities, Orders, Events). Un pannello scorre da destra quando prendi in carico e invii un'attività."},
  {k:'claim',r:"Il Claim assegna l'attività a te. Finché non la prendi in carico è non assegnata. Dopo il claim il modulo diventa modificabile; alcune attività sono auto-assegnate e saltano questo passo."},
  {k:'run rate',r:"Run Rate apre un grafico della velocità: velocità in tempo reale (blu) rispetto al target dell'ordine (verde) e alla nominale della macchina (giallo), più la media oraria. Se il blu sta sotto il verde sei sotto target."},
  {k:'activit',r:"La scheda Activities nella colonna destra è la tua lista di lavoro, filtrata su Active di default. Il contatore blu a sinistra mostra quante sono ancora aperte."},
  {k:'suspend',r:"Suspend Order sospende la produzione e conserva i contatori; Resume continua da dove si era fermato. Complete Order chiude l'ordine in modo definitivo. Usa Suspend per un'interruzione temporanea."},
  {k:'segment',r:"Il pulsante colorato del segmento nella barra superiore mostra lo stato macchina (stessi colori del Cockpit). Cliccandolo si apre il pannello Downtime Events per assegnare una causale di fermo — trattato in OP-06."},
  {k:'oee',r:"OEE = Disponibilità × Prestazioni × Qualità. Le tre percentuali del turno sono nella barra superiore. Un valore basso indica fermate, perdite di velocità o scarti."}
];


