/* ---------- DANSK (da) ---------- */
Object.assign(T.da, {











  'quiz.lbl.op03':"Spørgsmål {n} af 3 · OP-03",


});
T.da['op03.quiz']=[
  {q:"Hvad er hovedformålet med højre panel i Station View?",opts:["Det viser Cockpit-oversigten over hver linje","Det er der, den Activity, du vælger i arbejdslisten, åbnes, så du kan Claime og Submitte den","Det viser sitets råvarer"],correct:1,exp:"Udførelsespanelet glider ind fra højre: den aktivitet, du vælger i arbejdslisten, åbnes der for at blive claimet og submittet.",vis:"Højre: klik på en aktivitet → panelet glider ind → Claim → udfyld formularen → Submit."},
  {q:"Du åbner Activities-listen i højre kolonne, og den ser kort ud. Hvilket filter er anvendt som standard?",opts:["Intet filter — den viser altid alle aktiviteter","‘Active’-filteret — kun aktive aktiviteter, nyeste først","Et filter efter operatørnavn"],correct:1,exp:"Activities-fanen anvender som standard Active-filteret, så kun opgaver, der stadig skal gøres, vises. Fjern chippen for også at se de fuldførte.",vis:"Activities-fanen → chip ‘Active ×’ → kun aktive aktiviteter for den valgte ordre."},
  {q:"Hvor i Station View læser du den kørende ordre — SKU, faktisk kontra måltal, OEE og ordrestatus?",opts:["I højre kolonne, Orders-fanen","I venstre kolonne, PO Area","I højre handlingspanel"],correct:1,exp:"Venstre kolonne (PO Area) viser den kørende ordre: nummer, SKU, mængder, hastighed, OEE og status.",vis:"Venstre kolonne = PO Area: ordre #, SKU, produceret/mål, OEE, status."}
];
T.da['op03.cf']=[
  {k:'kolonne',r:"Station View har to kolonner og et handlingspanel: venstre = PO Area (din ordre), højre = arbejdslisten (Activities, Orders, Events). Et panel glider ind fra højre, når du claimer og submitter en opgave."},
  {k:'claim',r:"Claim tildeler aktiviteten til dig. Indtil den er claimet, er den utildelt. Når den er claimet, bliver formularen redigerbar; nogle aktiviteter claimes automatisk og springer dette trin over."},
  {k:'run rate',r:"Run Rate åbner et hastighedsdiagram: live-hastighed (blå) kontra ordremålet (grøn) og maskinens nominelle (gul), plus timegennemsnittet. Hvis blå ligger under grøn, er du under mål."},
  {k:'aktivitet',r:"Activities-fanen i højre kolonne er din opgaveliste, som standard filtreret til Active. Den blå tæller til venstre viser, hvor mange der stadig er åbne."},
  {k:'suspend',r:"Suspend Order sætter produktionen på pause og bevarer tællerne; Resume fortsætter, hvor den stoppede. Complete Order lukker den permanent. Brug Suspend til en midlertidig afbrydelse."},
  {k:'segment',r:"Den farvede segmentknap i topbjælken viser maskintilstanden (samme Cockpit-farver). Et klik åbner Downtime Events-panelet for at tildele en stopårsag — dækkes i OP-06."},
  {k:'oee',r:"OEE = Availability × Performance × Quality. De tre vagtprocenter er i topbjælken. Et lavt tal peger på stop, hastighedstab eller kassation."}
];

/* ---------- 简体中文 (zh) ---------- */
Object.assign(T.zh, {











  'quiz.lbl.op03':"第 {n} 题（共3题）· OP-03",


});
T.zh['op03.quiz']=[
  {q:"在 Station View 中，右侧面板的主要用途是什么？",opts:["它显示每条线的 Cockpit 概览","它是你在工作列表中选择的 Activity 打开的地方，以便你 Claim 并 Submit 它","它列出工厂的原材料"],correct:1,exp:"执行面板从右侧滑出：你在工作列表中选择的活动会在那里打开，以便被 claim 和 submit。",vis:"右侧：点击一个活动 → 面板滑出 → Claim → 填写表单 → Submit。"},
  {q:"你在右列打开 Activities 列表，它看起来很短。默认应用了哪个筛选？",opts:["没有筛选 — 它总是显示每个活动","‘Active’ 筛选 — 只显示活动中的活动，最新的在前","按操作员姓名筛选"],correct:1,exp:"Activities 选项卡默认使用 Active 筛选，因此只显示仍待办的任务。移除标签即可同时看到已完成的任务。",vis:"Activities 选项卡 → 标签 ‘Active ×’ → 只显示所选订单的活动中的活动。"},
  {q:"在 Station View 中，你在哪里读取正在运行的订单 — SKU、实际数量对比目标数量、OEE 和订单状态？",opts:["在右列的 Orders 选项卡","在左列的 PO Area","在右侧的操作面板"],correct:1,exp:"左列（PO Area）显示正在运行的订单：编号、SKU、数量、速度、OEE 和状态。",vis:"左列 = PO Area：订单 #、SKU、已生产/目标、OEE、状态。"}
];
T.zh['op03.cf']=[
  {k:'列',r:"Station View 有两列和一个操作面板：左 = PO Area（你的订单），右 = 工作列表（Activities、Orders、Events）。当你 claim 并 submit 一项任务时，面板会从右侧滑出。"},
  {k:'claim',r:"Claim 会把活动分配给你。在被 claim 之前它是未分配的。一旦被 claim，表单就变得可编辑；有些活动会自动 claim 并跳过此步骤。"},
  {k:'run rate',r:"Run Rate 会打开一个速度图表：实时速度（蓝色）对比订单目标（绿色）和机器额定值（黄色），以及每小时平均值。如果蓝色低于绿色，说明你低于目标。"},
  {k:'活动',r:"右列的 Activities 选项卡是你的任务列表，默认筛选为 Active。左侧的蓝色计数器显示还有多少个未完成。"},
  {k:'suspend',r:"Suspend Order 会暂停生产并保留计数器；Resume 会从停止处继续。Complete Order 会永久关闭它。临时中断请使用 Suspend。"},
  {k:'segment',r:"顶部栏中的彩色 Segment 按钮显示机器状态（与 Cockpit 颜色相同）。点击它会打开 Downtime Events 面板以分配停机原因 — 将在 OP-06 中讲解。"},
  {k:'oee',r:"OEE = Availability × Performance × Quality。三个班次百分比在顶部栏中。数值偏低说明存在停机、速度损失或废品。"}
];

/* ---------- NEDERLANDS (nl) ---------- */
Object.assign(T.nl, {











  'quiz.lbl.op03':"Vraag {n} van 3 · OP-03",


});
T.nl['op03.quiz']=[
  {q:"Wat is in Station View het hoofddoel van het rechterpaneel?",opts:["Het toont het Cockpit-overzicht van elke lijn","Het is waar de Activity die je in de werklijst selecteert opent, zodat je die kunt Claimen en Submitten","Het somt de grondstoffen van de site op"],correct:1,exp:"Het uitvoeringspaneel schuift van rechts in: de activiteit die je in de werklijst kiest, opent daar om geclaimd en gesubmit te worden.",vis:"Rechts: klik op een activiteit → paneel schuift in → Claim → vul het formulier in → Submit."},
  {q:"Je opent de Activities-lijst in de rechterkolom en die ziet er kort uit. Welk filter is standaard toegepast?",opts:["Geen filter — het toont altijd elke activiteit","Het ‘Active’-filter — alleen actieve activiteiten, nieuwste eerst","Een filter op operatornaam"],correct:1,exp:"Het Activities-tabblad gebruikt standaard het Active-filter, dus alleen taken die nog te doen zijn worden getoond. Verwijder de chip om ook de voltooide te zien.",vis:"Activities-tabblad → chip ‘Active ×’ → alleen actieve activiteiten voor de geselecteerde order."},
  {q:"Waar in Station View lees je de lopende order — SKU, werkelijke tegenover doelhoeveelheid, OEE en orderstatus?",opts:["In de rechterkolom, Orders-tabblad","In de linkerkolom, de PO Area","In het rechteractiepaneel"],correct:1,exp:"De linkerkolom (PO Area) toont de lopende order: nummer, SKU, hoeveelheden, snelheid, OEE en status.",vis:"Linkerkolom = PO Area: order #, SKU, geproduceerd/doel, OEE, status."}
];
T.nl['op03.cf']=[
  {k:'kolom',r:"Station View heeft twee kolommen en een actiepaneel: links = de PO Area (jouw order), rechts = de werklijst (Activities, Orders, Events). Een paneel schuift van rechts in wanneer je een taak claimt en submit."},
  {k:'claim',r:"Claimen wijst de activiteit aan jou toe. Tot ze geclaimd is, is ze niet toegewezen. Zodra ze geclaimd is, wordt het formulier bewerkbaar; sommige activiteiten worden automatisch geclaimd en slaan deze stap over."},
  {k:'run rate',r:"Run Rate opent een snelheidsgrafiek: live-snelheid (blauw) tegenover het orderdoel (groen) en de machine-nominale (geel), plus het uurgemiddelde. Als blauw onder groen ligt, zit je onder doel."},
  {k:'activiteit',r:"Het Activities-tabblad in de rechterkolom is je takenlijst, standaard gefilterd op Active. De blauwe teller links toont hoeveel er nog open zijn."},
  {k:'suspend',r:"Suspend Order pauzeert de productie en behoudt de tellers; Resume gaat verder vanaf waar het stopte. Complete Order sluit ze definitief af. Gebruik Suspend voor een tijdelijke onderbreking."},
  {k:'segment',r:"De gekleurde segmentknop in de bovenbalk toont de machinestatus (dezelfde Cockpit-kleuren). Erop klikken opent het Downtime Events-paneel om een stopreden toe te wijzen — behandeld in OP-06."},
  {k:'oee',r:"OEE = Availability × Performance × Quality. De drie dienstpercentages staan in de bovenbalk. Een laag cijfer wijst op stops, snelheidsverlies of afkeur."}
];

